CREATE TABLE `appointments` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `booking_code` varchar(13) NOT NULL,
  `patient_profile_id` bigint(20) unsigned NOT NULL,
  `practice_session_id` bigint(20) unsigned NOT NULL,
  `doctor_id` bigint(20) unsigned NOT NULL,
  `clinic_id` bigint(20) unsigned NOT NULL,
  `session_date` date NOT NULL,
  `queue_number` smallint(5) unsigned NOT NULL,
  `status` varchar(20) NOT NULL,
  `channel` varchar(10) NOT NULL,
  `payment_type` varchar(10) NOT NULL,
  `insurance_partner_id` bigint(20) unsigned DEFAULT NULL,
  `payment_reference` text DEFAULT NULL,
  `payment_reference_last4` char(4) DEFAULT NULL,
  `complaint` varchar(500) DEFAULT NULL,
  `created_by_user_id` bigint(20) unsigned DEFAULT NULL,
  `confirmed_at` datetime DEFAULT NULL,
  `checked_in_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `cancelled_at` datetime DEFAULT NULL,
  `no_show_at` datetime DEFAULT NULL,
  `cancelled_by_type` varchar(10) DEFAULT NULL,
  `cancelled_by_user_id` bigint(20) unsigned DEFAULT NULL,
  `cancel_reason` varchar(255) DEFAULT NULL,
  `schedule_changed_at` datetime DEFAULT NULL,
  `active_flag` tinyint(4) GENERATED ALWAYS AS (case when `status` in ('pending','confirmed','checked_in') then 1 else NULL end) STORED,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `appointments_practice_session_id_queue_number_unique` (`practice_session_id`,`queue_number`),
  UNIQUE KEY `appointments_booking_code_unique` (`booking_code`),
  UNIQUE KEY `appointments_patient_session_active_unique` (`patient_profile_id`,`practice_session_id`,`active_flag`),
  KEY `appointments_clinic_id_foreign` (`clinic_id`),
  KEY `appointments_insurance_partner_id_foreign` (`insurance_partner_id`),
  KEY `appointments_created_by_user_id_foreign` (`created_by_user_id`),
  KEY `appointments_cancelled_by_user_id_foreign` (`cancelled_by_user_id`),
  KEY `appointments_session_date_status_index` (`session_date`,`status`),
  KEY `appointments_patient_profile_id_session_date_index` (`patient_profile_id`,`session_date`),
  KEY `appointments_doctor_id_session_date_index` (`doctor_id`,`session_date`),
  KEY `appointments_status_index` (`status`),
  KEY `appointments_created_at_index` (`created_at`),
  CONSTRAINT `appointments_cancelled_by_user_id_foreign` FOREIGN KEY (`cancelled_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `appointments_clinic_id_foreign` FOREIGN KEY (`clinic_id`) REFERENCES `clinics` (`id`),
  CONSTRAINT `appointments_created_by_user_id_foreign` FOREIGN KEY (`created_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `appointments_doctor_id_foreign` FOREIGN KEY (`doctor_id`) REFERENCES `doctors` (`id`),
  CONSTRAINT `appointments_insurance_partner_id_foreign` FOREIGN KEY (`insurance_partner_id`) REFERENCES `insurance_partners` (`id`),
  CONSTRAINT `appointments_patient_profile_id_foreign` FOREIGN KEY (`patient_profile_id`) REFERENCES `patient_profiles` (`id`),
  CONSTRAINT `appointments_practice_session_id_foreign` FOREIGN KEY (`practice_session_id`) REFERENCES `practice_sessions` (`id`),
  CONSTRAINT `chk_appointments_queue` CHECK (`queue_number` >= 1)
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
