/*!40000 ALTER TABLE `articles` DISABLE KEYS */;
INSERT INTO `articles` VALUES (1,3,2,'Kebiasaan Sederhana untuk Menjaga Kesehatan Jantung','kebiasaan-sederhana-menjaga-kesehatan-jantung','Aktivitas fisik teratur, pola makan seimbang, dan istirahat cukup adalah kebiasaan umum yang mendukung kesehatan jantung.','<p>Menjaga kesehatan jantung tidak selalu dimulai dari langkah yang rumit. Kebiasaan harian seperti bergerak secara teratur, memilih makanan yang beragam, dan menyediakan waktu untuk beristirahat dapat menjadi dasar yang baik bagi tubuh.</p><p>Sesuaikan kegiatan dengan kemampuan Anda, misalnya berjalan kaki santai di sekitar rumah atau memilih tangga bila memungkinkan. Perubahan kecil yang dilakukan terus-menerus biasanya lebih mudah dipertahankan daripada perubahan besar yang sulit diikuti.</p><p>Informasi ini bersifat umum dan tidak menggantikan konsultasi dengan tenaga kesehatan.</p>','published','2026-10-07 07:10:03',NULL,NULL,'2026-10-10 00:10:03','2026-10-10 00:10:03',NULL),(2,1,2,'Mengapa Pemeriksaan Kesehatan Berkala Itu Penting','pentingnya-pemeriksaan-kesehatan-berkala','Pemeriksaan berkala membantu Anda mengenali kondisi tubuh dan berdiskusi dengan dokter tentang langkah pencegahan.','<p>Pemeriksaan kesehatan berkala adalah kesempatan untuk mengenal kondisi tubuh Anda dan membicarakannya dengan dokter. Dari percakapan tersebut, dokter dapat menjelaskan hal-hal yang perlu diperhatikan sesuai usia, riwayat keluarga, dan kebiasaan sehari-hari.</p><p>Sebelum datang, catat pertanyaan dan keluhan yang ingin Anda sampaikan, serta bawa catatan obat atau hasil pemeriksaan sebelumnya bila ada. Persiapan sederhana ini membantu pertemuan berjalan lebih terarah.</p><p>Informasi ini bersifat umum dan tidak menggantikan konsultasi dengan tenaga kesehatan.</p>','published','2026-10-04 07:10:03',NULL,NULL,'2026-10-10 00:10:03','2026-10-10 00:10:03',NULL),(3,4,2,'Menyiapkan Diri Sebelum Berkunjung ke Poliklinik','menyiapkan-diri-sebelum-berkunjung-ke-poliklinik','Catat keluhan, bawa dokumen yang diperlukan, dan datang lebih awal agar kunjungan berjalan lancar.','<p>Kunjungan ke poliklinik akan lebih lancar bila Anda menyiapkan beberapa hal sejak di rumah. Periksa jadwal dokter, pastikan sesi masih tersedia, lalu simpan bukti pendaftaran atau kode booking agar mudah ditunjukkan kepada petugas.</p><p>Catat keluhan dengan singkat, siapkan identitas diri, dan bawa kartu BPJS atau polis asuransi bila Anda memakainya. Datanglah sedikit lebih awal agar ada waktu untuk proses check-in dan pemanggilan antrean.</p><p>Informasi ini bersifat umum dan tidak menggantikan konsultasi dengan tenaga kesehatan.</p>','published','2026-10-01 07:10:03',NULL,NULL,'2026-10-10 00:10:03','2026-10-10 00:10:03',NULL),(4,2,2,'Mengenali Tanda Kekurangan Cairan pada Anak','mengenali-tanda-kekurangan-cairan-pada-anak','Anak yang rewel, jarang buang air kecil, atau tampak lemas perlu diperhatikan; hubungi tenaga kesehatan bila ragu.','<p>Anak yang kurang minum dapat terlihat lebih rewel, tampak lemas, atau jarang buang air kecil. Orang tua dapat memperhatikan kebiasaan minum anak dan menawarkan cairan secara bertahap sepanjang hari.</p><p>Bila Anda ragu dengan kondisi anak atau gejalanya tidak membaik, hubungi tenaga kesehatan atau kunjungi poliklinik anak agar mendapat penjelasan yang sesuai dengan keadaan anak Anda.</p><p>Informasi ini bersifat umum dan tidak menggantikan konsultasi dengan tenaga kesehatan.</p>','published','2026-09-28 07:10:04',NULL,NULL,'2026-10-10 00:10:04','2026-10-10 00:10:04',NULL),(5,3,2,'Pola Tidur yang Baik untuk Tubuh yang Bugar','pola-tidur-yang-baik-untuk-tubuh-bugar','Jadwal tidur yang konsisten dan lingkungan tidur yang nyaman membantu tubuh beristirahat dengan baik.','<p>Tidur yang cukup membantu tubuh beristirahat. Jadwal tidur dan bangun yang relatif konsisten dapat membantu tubuh mengenali waktu istirahatnya.</p><p>Lingkungan tidur yang nyaman, misalnya kamar yang tenang, gelap, dan sejuk, juga berperan. Mengurangi penggunaan layar menjelang tidur dan menghindari makan berat terlalu larut adalah kebiasaan yang dapat dicoba.</p><p>Informasi ini bersifat umum dan tidak menggantikan konsultasi dengan tenaga kesehatan.</p>','published','2026-09-25 07:10:04',NULL,NULL,'2026-10-10 00:10:04','2026-10-10 00:10:04',NULL),(6,1,2,'Cara Mencuci Tangan yang Benar','cara-mencuci-tangan-yang-benar','Mencuci tangan dengan sabun dan air mengalir adalah kebiasaan sederhana untuk membantu mencegah penularan penyakit.','<p>Mencuci tangan dengan sabun dan air mengalir adalah kebiasaan sederhana yang dapat membantu mencegah penularan penyakit. Lakukan sebelum makan, setelah dari toilet, dan setelah beraktivitas di tempat umum.</p><p>Basahi tangan, gosok seluruh permukaan termasuk punggung tangan, sela jari, dan ujung kuku, lalu bilas hingga bersih dan keringkan dengan lap bersih. Bila sabun dan air belum tersedia, cairan pembersih tangan dapat menjadi pilihan sementara.</p><p>Informasi ini bersifat umum dan tidak menggantikan konsultasi dengan tenaga kesehatan.</p>','published','2026-09-20 07:10:04',NULL,NULL,'2026-10-10 00:10:04','2026-10-10 00:10:04',NULL),(7,4,2,'Panduan Pendaftaran Online di UNPAM HOSPITAL','panduan-pendaftaran-online-unpam-hospital','Langkah membuat akun, memilih dokter dan sesi, hingga menyimpan bukti pendaftaran.','<p>Pendaftaran kunjungan rawat jalan dapat dilakukan lewat situs ini. Buat akun, masuk, lalu pilih poliklinik, dokter, tanggal, dan sesi yang tersedia.</p><p>Setelah mengisi data pendaftaran dan konfirmasi, simpan bukti pendaftaran yang memuat kode booking dan nomor antrean. Anda juga dapat mendaftar langsung di loket pendaftaran. Seluruh data pada situs prototipe ini adalah data contoh.</p><p>Informasi ini bersifat umum dan tidak menggantikan konsultasi dengan tenaga kesehatan.</p>','published','2026-10-09 07:10:04',NULL,NULL,'2026-10-10 00:10:04','2026-10-10 00:10:04',NULL),(8,1,2,'Draf: Menjaga Kesehatan di Musim Hujan','draf-menjaga-kesehatan-di-musim-hujan','Draf yang belum terbit — tidak boleh tampil di publik (uji status).','<p>Pergantian cuaca sering mengubah kebiasaan sehari-hari. Menjaga kebersihan, memilih makanan yang segar, dan beristirahat cukup dapat membantu tubuh tetap bugar.</p><p>Perhatikan juga kebersihan lingkungan sekitar rumah dan siapkan perlengkapan seperti jas hujan agar tidak mudah basah kuyup saat bepergian.</p><p>Informasi ini bersifat umum dan tidak menggantikan konsultasi dengan tenaga kesehatan.</p>','draft',NULL,NULL,NULL,'2026-10-10 00:10:04','2026-10-10 00:10:04',NULL);
/*!40000 ALTER TABLE `articles` ENABLE KEYS */;
UNLOCK TABLES;

