10-10 00:10:09'),(160,'system',NULL,'media.uploaded','App\\Models\\Media',79,'Gambar diunggah ke koleksi photos.',NULL,'{\"media_id\":79,\"collection\":\"photos\",\"file_name\":\"09853ab0-7642-4a7f-a511-3358ee821fce.jpg\"}',NULL,NULL,'2026-10-10 00:10:09'),(161,'system',NULL,'faq.created','App\\Models\\Faq',1,'FAQ \"Bagaimana cara mendaftar kunjungan rawat jalan secara online?\" ditambahkan.',NULL,'{\"category\":\"pendaftaran\",\"question\":\"Bagaimana cara mendaftar kunjungan rawat jalan secara online?\",\"answer\":\"Buat akun di halaman Daftar, masuk, pilih poliklinik, dokter, tanggal dan sesi, isi data pendaftaran, lalu konfirmasi. Bukti pendaftaran berisi kode booking dan nomor antrean dapat dicetak atau diunduh.\",\"sort_order\":1,\"is_published\":true,\"id\":1}',NULL,NULL,'2026-10-10 00:10:09'),(162,'system',NULL,'faq.created','App\\Models\\Faq',2,'FAQ \"Sampai berapa hari ke depan saya dapat mendaftar?\" ditambahkan.',NULL,'{\"category\":\"pendaftaran\",\"question\":\"Sampai berapa hari ke depan saya dapat mendaftar?\",\"answer\":\"Pendaftaran online dapat dilakukan untuk sesi sampai 30 hari ke depan.\",\"sort_order\":2,\"is_published\":true,\"id\":2}',NULL,NULL,'2026-10-10 00:10:09'),(163,'system',NULL,'faq.created','App\\Models\\Faq',3,'FAQ \"Kapan pendaftaran online untuk suatu sesi ditutup?\" ditambahkan.',NULL,'{\"category\":\"pendaftaran\",\"question\":\"Kapan pendaftaran online untuk suatu sesi ditutup?\",\"answer\":\"Pendaftaran online ditutup 60 menit sebelum sesi dimulai. Setelah itu Anda dapat mendaftar langsung di loket selama sesi belum berakhir dan kuota masih tersedia.\",\"sort_order\":3,\"is_published\":true,\"id\":3}',NULL,NULL,'2026-10-10 00:10:09'),(164,'system',NULL,'faq.created','App\\Models\\Faq',4,'FAQ \"Bagaimana cara membatalkan pendaftaran?\" ditambahkan.',NULL,'{\"category\":\"pendaftaran\",\"question\":\"Bagaimana cara membatalkan pendaftaran?\",\"answer\":\"Buka Riwayat Pendaftaran lalu pilih Batalkan, paling lambat 120 menit sebelum sesi dimulai. Setelah batas itu, hubungi rumah sakit melalui telepon atau WhatsApp.\",\"sort_order\":4,\"is_published\":true,\"id\":4}',NULL,NULL,'2026-10-10 00:10:09'),(165,'system',NULL,'faq.created','App\\Models\\Faq',5,'FAQ \"Apa yang perlu saya bawa saat datang?\" ditambahkan.',NULL,'{\"category\":\"pendaftaran\",\"question\":\"Apa yang perlu saya bawa saat datang?\",\"answer\":\"Tunjukkan kode booking atau bukti pendaftaran, identitas diri, serta kartu BPJS atau polis asuransi bila memakainya. Check-in dibuka 60 menit sebelum sesi dimulai.\",\"sort_order\":5,\"is_published\":true,\"id\":5}',NULL,NULL,'2026-10-10 00:10:09'),(166,'system',NULL,'faq.created','App\\Models\\Faq',6,'FAQ \"Apakah saya bisa mendaftar tanpa akun?\" ditambahkan.',NULL,'{\"category\":\"pendaftaran\",\"question\":\"Apakah saya bisa mendaftar tanpa akun?\",\"answer\":\"Bisa. Datang ke loket pendaftaran; petugas dapat membuat profil pasien dan mendaftarkan kunjungan Anda. Kuota dibagi bersama pendaftaran online.\",\"sort_order\":6,\"is_published\":true,\"id\":6}',NULL,NULL,'2026-10-10 00:10:09'),(167,'system',NULL,'faq.created','App\\Models\\Faq',7,'FAQ \"Apakah nomor BPJS wajib diisi?\" ditambahkan.',NULL,'{\"category\":\"bpjs\",\"question\":\"Apakah nomor BPJS wajib diisi?\",\"answer\":\"Hanya jika Anda memilih jenis pembayaran BPJS Kesehatan (13 digit). Untuk pembayaran umum atau asuransi, nomor BPJS tidak diminta.\",\"sort_order\":7,\"is_published\":true,\"id\":7}',NULL,NULL,'2026-10-10 00:10:09'),(168,'system',NULL,'faq.created','App\\Models\\Faq',8,'FAQ \"Apakah saya perlu mengisi NIK?\" ditambahkan.',NULL,'{\"category\":\"bpjs\",\"question\":\"Apakah saya perlu mengisi NIK?\",\"answer\":\"Tidak. Sistem ini tidak meminta NIK.\",\"sort_order\":8,\"is_published\":true,\"id\":8}',NULL,NULL,'2026-10-10 00:10:09'),(169,'system',NULL,'faq.created','App\\Models\\Faq',9,'FAQ \"Apakah jadwal dokter dapat berubah?\" ditambahkan.',NULL,'{\"category\":\"layanan\",\"question\":\"Apakah jadwal dokter dapat berubah?\",\"answer\":\"Dapat berubah, misalnya karena cuti. Bila jadwal Anda terdampak, petugas menindaklanjuti dan Anda menerima pemberitahuan di akun atau melalui telepon yang tercatat.\",\"sort_order\":9,\"is_published\":true,\"id\":9}',NULL,NULL,'2026-10-10 00:10:09'),(170,'system',NULL,'faq.created','App\\Models\\Faq',10,'FAQ \"Apakah ketersediaan kamar rawat inap bersifat real-time?\" ditambahkan.',NULL,'{\"category\":\"layanan\",\"question\":\"Apakah ketersediaan kamar rawat inap bersifat real-time?\",\"answer\":\"Tidak. Ketersediaan diperbarui manual oleh petugas dan waktu pembaruan terakhir ditampilkan. Hubungi rumah sakit untuk memastikan ketersediaan.\",\"sort_order\":10,\"is_published\":true,\"id\":10}',NULL,NULL,'2026-10-10 00:10:09'),(171,'system',NULL,'faq.created','App\\Models\\Faq',11,'FAQ \"Bagaimana data pribadi saya dilindungi?\" ditambahkan.',NULL,'{\"category\":\"umum\",\"question\":\"Bagaimana data pribadi saya dilindungi?\",\"answer\":\"Data hanya digunakan untuk pendaftaran kunjungan, nomor BPJS disimpan terenkripsi, dan akses dibatasi bagi petugas berwenang. Baca Kebijakan Privasi untuk rinciannya.\",\"sort_order\":11,\"is_published\":true,\"id\":11}',NULL,NULL,'2026-10-10 00:10:09'),(172,'system',NULL,'faq.created','App\\Models\\Faq',12,'FAQ \"Bagaimana menghubungi rumah sakit?\" ditambahkan.',NULL,'{\"category\":\"umum\",\"question\":\"Bagaimana menghubungi rumah sakit?\",\"answer\":\"Gunakan halaman Kontak dan Lokasi atau tombol WhatsApp. Tombol WhatsApp hanya membuka aplikasi WhatsApp dan pesan dikirim sendiri oleh Anda; bukan pengiriman otomatis. Nomor pada prototipe ini adalah placeholder.\",\"sort_order\":12,\"is_published\":true,\"id\":12}',NULL,NULL,'2026-10-10 00:10:09'),(173,'system',NULL,'insurance_partner.created','App\\Models\\InsurancePartner',1,'Mitra asuransi \"Asuransi Contoh Sehat\" ditambahkan.',NULL,'{\"name\":\"Asuransi Contoh Sehat\",\"slug\":\"asuransi-contoh-sehat\",\"type\":\"asuransi\",\"description\