INSERT INTO `contact_messages` VALUES (1,'Rudi Hartono','rudi@contoh.test',NULL,'Pertanyaan jam operasional','Selamat pagi. Mohon informasi jam operasional poliklinik pada hari Sabtu dan hari libur. Terima kasih.','new','2026-10-05 07:10:14','76713f7483c2e58e5310f03019bd2bd2714d08d473906c23cc09442769982ee6',NULL,NULL,'2026-10-05 00:10:14','2026-10-05 00:10:14'),(2,'Sinta Maharani','sinta@contoh.test','081234567890','Menanyakan ketersediaan kamar VIP','Saya ingin menanyakan apakah kamar VIP masih tersedia untuk beberapa hari ke depan. Mohon informasinya.','new','2026-10-06 07:10:14','76713f7483c2e58e5310f03019bd2bd2714d08d473906c23cc09442769982ee6',NULL,NULL,'2026-10-06 00:10:14','2026-10-06 00:10:14'),(3,'Tono Wibisono','tono@contoh.test',NULL,'Saran tampilan jadwal dokter','Tampilan jadwal dokter sudah cukup jelas. Saran saya, tambahkan keterangan hari libur pada setiap minggu.','read','2026-10-07 07:10:14','76713f7483c2e58e5310f03019bd2bd2714d08d473906c23cc09442769982ee6',NULL,NULL,'2026-10-07 00:10:14','2026-10-07 00:10:14'),(4,'Wati Kusuma','wati@contoh.test',NULL,'Perubahan data profil','Saya ingin mengubah data profil pada akun saya. Mohon petunjuk langkah yang perlu dilakukan.','replied','2026-10-08 07:10:14','76713f7483c2e58e5310f03019bd2bd2714d08d473906c23cc09442769982ee6',3,'2026-10-08 08:10:14','2026-10-08 00:10:14','2026-10-08 01:10:14'),(5,'Vina Oktaviana','vina@contoh.test',NULL,'Pesan uji (diarsipkan)','Ini adalah pesan uji yang sudah diarsipkan oleh petugas. Tidak ada tindak lanjut yang diperlukan.','archived','2026-10-09 07:10:14','76713f7483c2e58e5310f03019bd2bd2714d08d473906c23cc09442769982ee6',3,'2026-10-09 08:10:14','2026-10-09 00:10:14','2026-10-09 01:10:14');
