--
-- Table structure for table `doctor_schedules`
--

DROP TABLE IF EXISTS `doctor_schedules`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `doctor_schedules` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `doctor_id` bigint(20) unsigned NOT NULL,
  `clinic_id` bigint(20) unsigned NOT NULL,
  `day_of_week` tinyint(3) unsigned NOT NULL,
  `start_time` time NOT NULL,
  `end_time` time NOT NULL,
  `quota` smallint(5) unsigned NOT NULL,
  `valid_from` date NOT NULL,
  `valid_until` date DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `notes` varchar(255) DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `doctor_schedules_clinic_id_foreign` (`clinic_id`),
  KEY `doctor_schedules_created_by_foreign` (`created_by`),
  KEY `doctor_schedules_updated_by_foreign` (`updated_by`),
  KEY `doctor_schedules_doctor_id_day_of_week_is_active_index` (`doctor_id`,`day_of_week`,`is_active`),
  KEY `doctor_schedules_is_active_valid_from_valid_until_index` (`is_active`,`valid_from`,`valid_until`),
  CONSTRAINT `doctor_schedules_clinic_id_foreign` FOREIGN KEY (`clinic_id`) REFERENCES `clinics` (`id`),
  CONSTRAINT `doctor_schedules_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `doctor_schedules_doctor_id_foreign` FOREIGN KEY (`doctor_id`) REFERENCES `doctors` (`id`),
  CONSTRAINT `doctor_schedules_updated_by_foreign` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `chk_schedules_time` CHECK (`end_time` > `start_time`),
  CONSTRAINT `chk_schedules_day` CHECK (`day_of_week` between 1 and 7),
  CONSTRAINT `chk_schedules_quota` CHECK (`quota` between 1 and 200),
  CONSTRAINT `chk_schedules_validity` CHECK (`valid_until` is null or `valid_until` >= `valid_from`)
) ENGINE=InnoDB AUTO_INCREMENT=53 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

