INSERT INTO `faqs` VALUES (1,'pendaftaran','Bagaimana cara mendaftar kunjungan rawat jalan secara online?','Buat akun di halaman Daftar, masuk, pilih poliklinik, dokter, tanggal dan sesi, isi data pendaftaran, lalu konfirmasi. Bukti pendaftaran berisi kode booking dan nomor antrean dapat dicetak atau diunduh.',1,1,'2026-10-10 00:10:09','2026-10-10 00:10:09'),(2,'pendaftaran','Sampai berapa hari ke depan saya dapat mendaftar?','Pendaftaran online dapat dilakukan untuk sesi sampai 30 hari ke depan.',2,1,'2026-10-10 00:10:09','2026-10-10 00:10:09'),(3,'pendaftaran','Kapan pendaftaran online untuk suatu sesi ditutup?','Pendaftaran online ditutup 60 menit sebelum sesi dimulai. Setelah itu Anda dapat mendaftar langsung di loket selama sesi belum berakhir dan kuota masih tersedia.',3,1,'2026-10-10 00:10:09','2026-10-10 00:10:09'),(4,'pendaftaran','Bagaimana cara membatalkan pendaftaran?','Buka Riwayat Pendaftaran lalu pilih Batalkan, paling lambat 120 menit sebelum sesi dimulai. Setelah batas itu, hubungi rumah sakit melalui telepon atau WhatsApp.',4,1,'2026-10-10 00:10:09','2026-10-10 00:10:09'),(5,'pendaftaran','Apa yang perlu saya bawa saat datang?','Tunjukkan kode booking atau bukti pendaftaran, identitas diri, serta kartu BPJS atau polis asuransi bila memakainya. Check-in dibuka 60 menit sebelum sesi dimulai.',5,1,'2026-10-10 00:10:09','2026-10-10 00:10:09'),(6,'pendaftaran','Apakah saya bisa mendaftar tanpa akun?','Bisa. Datang ke loket pendaftaran; petugas dapat membuat profil pasien dan mendaftarkan kunjungan Anda. Kuota dibagi bersama pendaftaran online.',6,1,'2026-10-10 00:10:09','2026-10-10 00:10:09'),(7,'bpjs','Apakah nomor BPJS wajib diisi?','Hanya jika Anda memilih jenis pembayaran BPJS Kesehatan (13 digit). Untuk pembayaran umum atau asuransi, nomor BPJS tidak diminta.',7,1,'2026-10-10 00:10:09','2026-10-10 00:10:09'),(8,'bpjs','Apakah saya perlu mengisi NIK?','Tidak. Sistem ini tidak meminta NIK.',8,1,'2026-10-10 00:10:09','2026-10-10 00:10:09'),(9,'layanan','Apakah jadwal dokter dapat berubah?','Dapat berubah, misalnya karena cuti. Bila jadwal Anda terdampak, petugas menindaklanjuti dan Anda menerima pemberitahuan di akun atau melalui telepon yang tercatat.',9,1,'2026-10-10 00:10:09','2026-10-10 00:10:09'),(10,'layanan','Apakah ketersediaan kamar rawat inap bersifat real-time?','Tidak. Ketersediaan diperbarui manual oleh petugas dan waktu pembaruan terakhir ditampilkan. Hubungi rumah sakit untuk memastikan ketersediaan.',10,1,'2026-10-10 00:10:09','2026-10-10 00:10:09'),(11,'umum','Bagaimana data pribadi saya dilindungi?','Data hanya digunakan untuk pendaftaran kunjungan, nomor BPJS disimpan terenkripsi, dan akses dibatasi bagi petugas berwenang. Baca Kebijakan Privasi untuk rinciannya.',11,1,'2026-10-10 00:10:09','2026-10-10 00:10:09'),(12,'umum','Bagaimana menghubungi rumah sakit?','Gunakan halaman Kontak dan Lokasi atau tombol WhatsApp. Tombol WhatsApp hanya membuka aplikasi WhatsApp dan pesan dikirim sendiri oleh Anda; bukan pengiriman otomatis. Nomor pada prototipe ini adalah placeholder.',12,1,'2026-10-10 00:10:09','2026-10-10 00:10:09');
/*!40000 ALTER TABLE `faqs` ENABLE KEYS */;
UNLOCK TABLES;

