  `consent_at` datetime NOT NULL,
  `consent_version` varchar(20) NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `patient_profiles_user_id_unique` (`user_id`),
  UNIQUE KEY `patient_profiles_patient_number_unique` (`patient_number`),
  KEY `patient_profiles_created_by_user_id_foreign` (`created_by_user_id`),
  KEY `patient_profiles_full_name_index` (`full_name`),
  KEY `patient_profiles_phone_index` (`phone`),
  CONSTRAINT `patient_profiles_created_by_user_id_foreign` FOREIGN KEY (`created_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `patient_profiles_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
