--
-- Table structure for table `practice_sessions`
--

DROP TABLE IF EXISTS `practice_sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `practice_sessions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `doctor_id` bigint(20) unsigned NOT NULL,
  `clinic_id` bigint(20) unsigned NOT NULL,
  `doctor_schedule_id` bigint(20) unsigned DEFAULT NULL,
  `session_date` date NOT NULL,
  `start_time` time NOT NULL,
  `end_time` time NOT NULL,
  `quota` smallint(5) unsigned NOT NULL,
  `booked_count` smallint(5) unsigned NOT NULL DEFAULT 0,
  `last_queue_number` smallint(5) unsigned NOT NULL DEFAULT 0,
  `status` varchar(20) NOT NULL DEFAULT 'open',
  `status_reason` varchar(255) DEFAULT NULL,
  `schedule_exception_id` bigint(20) unsigned DEFAULT NULL,
  `pending_change` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`pending_change`)),
  `is_manually_modified` tinyint(1) NOT NULL DEFAULT 0,
  `reviewed_by` bigint(20) unsigned DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `practice_sessions_doctor_schedule_id_session_date_unique` (`doctor_schedule_id`,`session_date`),
  KEY `practice_sessions_schedule_exception_id_foreign` (`schedule_exception_id`),
  KEY `practice_sessions_reviewed_by_foreign` (`reviewed_by`),
  KEY `practice_sessions_session_date_status_index` (`session_date`,`status`),
  KEY `practice_sessions_doctor_id_session_date_index` (`doctor_id`,`session_date`),
  KEY `practice_sessions_clinic_id_session_date_index` (`clinic_id`,`session_date`),
  CONSTRAINT `practice_sessions_clinic_id_foreign` FOREIGN KEY (`clinic_id`) REFERENCES `clinics` (`id`),
  CONSTRAINT `practice_sessions_doctor_id_foreign` FOREIGN KEY (`doctor_id`) REFERENCES `doctors` (`id`),
  CONSTRAINT `practice_sessions_doctor_schedule_id_foreign` FOREIGN KEY (`doctor_schedule_id`) REFERENCES `doctor_schedules` (`id`) ON DELETE SET NULL,
  CONSTRAINT `practice_sessions_reviewed_by_foreign` FOREIGN KEY (`reviewed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `practice_sessions_schedule_exception_id_foreign` FOREIGN KEY (`schedule_exception_id`) REFERENCES `schedule_exceptions` (`id`) ON DELETE SET NULL,
